import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { updateDiscussion } from "../handlers/updateDiscussion";
import type { ApiError } from "../runtime/client";
import type { SpacePartition } from "../types/SpacePartition";
import type { SpacePostEntityType } from "../types/SpacePostEntityType";
import type { UpdateDiscussionRequest } from "../types/UpdateDiscussionRequest";

type Data = Awaited<ReturnType<typeof updateDiscussion>>;
type Vars = { spaceId: SpacePartition; discussionSk: SpacePostEntityType; req: UpdateDiscussionRequest };

export function useUpdateDiscussion(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => updateDiscussion(vars.spaceId, vars.discussionSk, vars.req),
    ...options,
  });
}
